    "summary": "Синдромологія потрібна для швидкого переходу від скарги або неврологічного знака до рівня ураження: кора, стовбур, спинний мозок, корінець, периферичний нерв, м’яз, нервово-м’язовий синапс, судинний басейн, ліквородинаміка або дифузне порушення свідомості.",
