          "Синдром - це не один симптом, а стійка комбінація ознак із певним темпом розвитку. Для неврологічної топіки важливі рух, чутливість, рефлекси, черепні нерви, мова, координація, тазові функції, свідомість і час появи симптомів.",
          "Раптовий фокальний дефіцит веде до судинної події; години-дні з гарячкою або менінгеальними знаками - до інфекції; підгостра дисемінація симптомів - до демієлінізації; повільне прогресування - до пухлини або дегенеративного процесу. Нападоподібність із повним відновленням змушує думати про епілептичний, мігренозний, вестибулярний або транзиторний судинний механізм."
