          "У цій темі відповідь зазвичай тримається на патерні: повільно прогресуюче нейродегенеративне захворювання, флуктуюча слабкість нервово-м’язового синапсу, дитяча м’язова дистрофія, поєднання верхнього і нижнього мотонейрона або центральна порожнина спинного мозку з дисоційованою чутливістю.",
