    "summary": "Судинні ураження нервової системи у КРОК перевіряються через раптовість, судинний басейн, тип інсульту, перше зображення, часові вікна реперфузії, різницю між артеріальним і венозним процесом, спінальні судинні синдроми, інсульт-міміки та причини інсульту в молодому віці.",
