        "paragraphs": [
          "Раптовий фокальний дефіцит вважається інсультом, доки не доведено інше. Перша дія - глюкоза, неврологічна шкала, час останнього нормального стану, КТ без контрасту для виключення крововиливу, далі судинна візуалізація, якщо можлива тромбектомія.",
          "Ішемічний інсульт дає дефіцит за артеріальним басейном і потребує вирішення питання про тромболізис або тромбектомію. Геморагічний інсульт частіше супроводжується головним болем, блюванням, швидким пригніченням свідомості, високим тиском або антикоагулянтами. Церебральний венозний тромбоз часто має головний біль, судоми, папіледему і не вкладається в один артеріальний басейн.",
          "Для тесту важливі стабільні принципи: КТ перед антиагрегантами, не знижувати тиск агресивно при ішемічному інсульті без показань, швидко реверсувати антикоагуляцію при крововиливі, не боятися антикоагуляції при підтвердженому церебральному венозному тромбозі (CVST) навіть за наявності венозного геморагічного інфаркту."
        ]
