    "sectionCode": "8.0.0.0",
    "updatedAt": "2026-06-30",
    "summary": "Патологія вегетативної нервової системи у КРОК зазвичай зводиться до впізнавання автономного дефіциту, мігрені, феномену Рейно та тригемінально-автономних прозопалгій. Найважливіше не переплутати вегетативні прояви з судинною катастрофою, інфекцією, вестибулярним міміком або вторинним головним болем.",
    "coverageHighlights": [
      "Ортостатична гіпотензія і автономна недостатність",
      "Мігрень, аура і головний біль через надмірне вживання ліків",
      "Рейно і вторинні ангіотрофоневрози",
      "Кластерний біль та інші тригемінально-автономні прозопалгії",
      "Автономні проби, профілактика нападів і червоні прапорці",
      "Меньєр, абузусний головний біль, комплексний регіонарний больовий синдром і центральні міміки"
    ],
