          "Гостре лікування: НПЗП або парацетамол, часто комбінація триптану з НПЗП/парацетамолом, плюс протиблювотний засіб за потреби. Профілактику розглядають при частих, тяжких або інвалідизуючих нападах; важливо питати про надмірне вживання анальгетиків. Комбіновані гормональні контрацептиви не пропонують рутинно при мігрені з аурою через судинний ризик."
