    "summary": "Травми нервової системи у КРОК перевіряють не травматологічні деталі, а неврологічне сортування: рівень свідомості за шкалою коми Глазго (GCS), ознаки внутрішньочерепної гематоми, показання до термінової КТ, первинну стабілізацію та розпізнавання травми спинного мозку.",
