    "sectionCode": "13.0.0.0",
    "updatedAt": "2026-06-30",
    "summary": "Екзогенні фактори в цьому блоці - це не вся токсикологія, а три перевірювані КРОК-напрями: свинець, талій та іонізуюче випромінювання. У задачах вирішують експозиція, поєднання неврологічних і системних ознак, а також правильний антидот або тактика безпеки.",
    "coverageHighlights": [
      "Свинець: звисання кисті, абдомінальна коліка і хелатори",
      "Талій: болюча полінейропатія, алопеція і берлінська блакить",
      "Гострий променевий синдром і лімфоцитопенія",
      "Радіаційна мієлопатія і радіаційний некроз",
      "Антидоти, деконтамінація і відмежування від синдрому Гійєна-Барре (GBS)/пухлини",
      "CO, фосфорорганіка, ботулізм і миш’як як токсичні міміки"
    ],
